<?php declare(strict_types=1);$owner=$p['role']==='owner';$latest=[];foreach($grants as$g)if(($latest[$g['trade_item_id']]['version']??0)<$g['version'])$latest[$g['trade_item_id']]=$g;$fields=['name'=>'Denumire','category'=>'Categorie','ingredients'=>'Ingrediente','allergens'=>'Alergeni','net_quantity'=>'Cantitate','operator'=>'Operator','storage'=>'Păstrare','nutrition'=>'Nutriție','origin'=>'Origine']; ?>
<div class="container page-space"><a class="back-link" href="/manage/sources">← Surse externe</a><div class="eyebrow">DISTRIBUIRE VOLUNTARĂ</div><h1 class="page-title">Open Food Facts</h1><p class="lead">Pregătește informațiile aprobate pentru importul în spațiul tău de producător Open Food Facts.</p><div class="notice"><p>Pregătirea sau descărcarea unui pachet nu confirmă publicarea în Open Food Facts. Trimiterea directă automată este oprită.</p></div>
<div class="admin-columns"><section class="panel"><h2>Organizația</h2><p><?=e($connection['connection']['remote_organization_ref']??'Nicio conexiune configurată')?></p><?php if($owner):?><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="connect"><label>Denumirea organizației în Open Food Facts<input class="form-control" name="organization_ref" maxlength="180" required></label><label>Confirmă parola dacă sesiunea depășește 15 minute<input type="password" name="current_password" autocomplete="current-password" class="form-control"></label><button class="btn btn-primary">Păstrează conexiunea pentru pachete</button></form><?php if($connection['connection']):?><form method="post" class="mt-3"><?=csrf()?><input type="hidden" name="action" value="disconnect"><input type="password" name="current_password" autocomplete="current-password" aria-label="Parola pentru confirmare" class="form-control mb-2"><button class="btn btn-outline-primary">Oprește distribuirea</button></form><?php endif?><?php endif?></section>
<section class="panel"><h2>Acord pentru un articol</h2><?php if($owner&&$items):?><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="grant"><label>Articol cu GTIN verificat<select name="trade_item_id" class="form-select" data-sharing-items><?php foreach($items as$item):?><option value="<?=e($item['id'])?>" data-grant-version="<?=e($latest[$item['id']]['version']??0)?>"><?=e($item['name'])?></option><?php endforeach?></select></label><fieldset><legend class="h6">Informații distribuite</legend><?php foreach($fields as$key=>$name):?><label class="check-label"><input type="checkbox" name="fields[]" value="<?=e($key)?>" <?=in_array($key,['name','ingredients','net_quantity'],true)?'checked':''?>> <?=e($name)?></label><?php endforeach?></fieldset><input type="hidden" name="expected_version" value="<?=e($latest[$items[0]['id']]['version']??0)?>"><label class="check-label"><input type="checkbox" name="public_data_confirmed" value="1" required> Am dreptul să distribui public informațiile selectate.</label><label class="check-label"><input type="checkbox" name="licenses_confirmed" value="1" required> Accept distribuirea sub ODbL și DbCL. Revocarea oprește transmiterile viitoare; copiile publice deja distribuite pot rămâne disponibile.</label><label>Confirmă parola dacă sesiunea depășește 15 minute<input type="password" name="current_password" autocomplete="current-password" class="form-control"></label><button class="btn btn-primary">Înregistrează acordul</button></form><?php else:?><p>Acordurile sunt administrate de proprietarul organizației pentru articole cu mandat GTIN verificat.</p><?php endif?></section></div>
<section class="panel"><h2>Acorduri și versiuni</h2><?php if(!$grants):?><p>Nu există acorduri înregistrate.</p><?php endif?><?php foreach($grants as$grant):?><div class="list-row"><span><strong>Versiunea <?=e($grant['version'])?></strong><small><?=e($grant['action']==='revoke'?'Revocare':'Acord')?> · <?=e(implode(', ',array_map(static fn($key)=>$fields[$key]??$key,$grant['fields'])))?></small></span><?php if($owner&&$grant['action']==='grant'&&($latest[$grant['trade_item_id']]['id']??null)===$grant['id']):?><form method="post"><?=csrf()?><input type="hidden" name="action" value="revoke"><input type="hidden" name="resource_id" value="<?=e($grant['id'])?>"><input type="password" name="current_password" autocomplete="current-password" aria-label="Parola pentru confirmare" class="form-control mb-2"><button class="btn btn-outline-primary">Revocă această versiune</button></form><?php endif?></div><?php endforeach?></section>
<section class="panel"><h2>Pregătește un pachet</h2><?php if($items):?><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="publication"><label>Articol<select class="form-select" name="trade_item_id"><?php foreach($items as$item):?><option value="<?=e($item['id'])?>"><?=e($item['name'])?></option><?php endforeach?></select></label><label class="check-label"><input type="checkbox" name="independently_verified" value="1"> Am verificat independent pe etichetă datele preluate anterior dintr-o sursă externă și confirm dreptul de distribuire.</label><button class="btn btn-primary">Pregătește versiunea publicată</button></form><?php endif?><h3 class="mt-4">Istoric</h3><?php foreach($publications as$publication):?><div class="list-row"><span><strong><?=e(['package_ready'=>'Pachet pregătit','cancelled'=>'Distribuire oprită','confirmed'=>'Confirmat de sursă'][$publication['state']]??$publication['state'])?></strong><small><?=e(ro_time($publication['created_at']))?></small></span><?php if($publication['state']==='package_ready'):?><a class="btn btn-outline-primary" href="/api/v2/manage/sources/openfoodfacts/publications/<?=e($publication['id'])?>/package">Descarcă pachetul</a><?php endif?></div><?php endforeach?></section></div>

